-- Gold-depth correction of four Year 3 lessons; no new lesson keys.

UPDATE lessons SET title='Mental Addition: Make Tens, Split and Check',data=json_patch(data,'{"seed_key":"s2-mat-y3-w05-l2","title":"Mental Addition: Make Tens, Split and Check","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":5,"lesson_number":2,"duration_minutes":60,"child_mission":"Investigate mental addition: make tens, split and check through an original worked model, practice and an independent challenge.","learning_intention":"We are learning to use mental addition: make tens, split and check and explain why the method works.","success_criteria":["I can explain a taught concept in my own words.","I can follow a worked example and identify important steps.","I can complete guided practice with feedback.","I can solve an independent challenge.","I can check and explain one improvement."],"materials":["All examples and reading are provided.","Optional paper, pencil and counters."],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four key ideas","cards":[{"front":"Make a friendly ten","back":"Move part of one addend to create a multiple of ten without changing the total."},{"front":"Split into tens and ones","back":"Separate place values, add the tens and ones, then regroup if needed."},{"front":"Count on in parts","back":"Start with the larger number and add tens before ones."},{"front":"Check with inverse subtraction","back":"Subtract one original addend from the sum to recover the other."}]}],"printable_resource":{"title":"Mental Addition: Make Tens, Split and Check","instructions":"Read, practise and complete the original challenge, then check.","passage":"A bookstall has 48 books and receives another 27.","prompts":["What is given?","What is the useful method?","What did I find?","How did I check it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Make a friendly ten","explain":"**Understand:** Move part of one addend to create a multiple of ten without changing the total.\n\n**Original example:** A bookstall has 48 books and receives another 27.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 48+27=50+25=75. I moved 2 from 27 to 48, rather than adding two extra.\n\n**YOUR TURN:** 36+19=36+20−1=55. 64+28=64+20+8=92. 47+35=(40+30)+(7+5)=82. Verify 82−35=47. Explain why 58+26 is 84, not 74.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Move part of one addend to create a multiple of ten without changing the total.","check":{"question":"48+27?","options":["65","75","85","74"],"correct_index":1,"explanation":"48+27=50+25=75. I moved 2 from 27 to 48, rather than adding two extra."},"visual_before":[{"episode":{"title":"Learning Mental Addition: Make Tens, Split and Check","transcript":"Pip: I have forty-eight books and twenty-seven more. How can I make it easier?\nJuno: Move two from twenty-seven to forty-eight: fifty plus twenty-five.\nPip: That''s seventy-five, so the moved two did not change the total.\nJuno: Pause and try adding twenty first, then seven, as a second check.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I have forty-eight books and twenty-seven more. How can I make it easier?"},{"who":"juno","text":"Move two from twenty-seven to forty-eight: fifty plus twenty-five."},{"who":"pip","text":"That''s seventy-five, so the moved two did not change the total."},{"who":"juno","text":"Pause and try adding twenty first, then seven, as a second check.","pause_after":true}]}]}}]},{"icon":"📚","title":"Split into tens and ones","explain":"**Understand:** Separate place values, add the tens and ones, then regroup if needed.\n\n**Original example:** A bookstall has 48 books and receives another 27.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 48+27=(40+20)+(8+7)=60+15=75.\n\n**YOUR TURN:** 36+19=36+20−1=55. 64+28=64+20+8=92. 47+35=(40+30)+(7+5)=82. Verify 82−35=47. Explain why 58+26 is 84, not 74.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Separate place values, add the tens and ones, then regroup if needed.","check":{"question":"50+25?","options":["65","70","75","80"],"correct_index":2,"explanation":"48+27=(40+20)+(8+7)=60+15=75."}},{"icon":"✍️","title":"Count on in parts","explain":"**Understand:** Start with the larger number and add tens before ones.\n\n**Original example:** A bookstall has 48 books and receives another 27.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 48→68 (+20)→75 (+7). Two jumps total 27.\n\n**YOUR TURN:** 36+19=36+20−1=55. 64+28=64+20+8=92. 47+35=(40+30)+(7+5)=82. Verify 82−35=47. Explain why 58+26 is 84, not 74.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Start with the larger number and add tens before ones.","check":{"question":"36+19?","options":["54","55","56","65"],"correct_index":1,"explanation":"48→68 (+20)→75 (+7). Two jumps total 27."}},{"icon":"✅","title":"Check with inverse subtraction","explain":"**Understand:** Subtract one original addend from the sum to recover the other.\n\n**Original example:** A bookstall has 48 books and receives another 27.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 75−27=48, confirming the original addition.\n\n**YOUR TURN:** 36+19=36+20−1=55. 64+28=64+20+8=92. 47+35=(40+30)+(7+5)=82. Verify 82−35=47. Explain why 58+26 is 84, not 74.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Subtract one original addend from the sum to recover the other.","check":{"question":"64+28?","options":["82","92","102","88"],"correct_index":1,"explanation":"75−27=48, confirming the original addition."}}],"worked_example":"**Original case:** A bookstall has 48 books and receives another 27.\n\n**Step 1: Make a friendly ten.** 48+27=50+25=75. I moved 2 from 27 to 48, rather than adding two extra.\n\n**Step 2: Split into tens and ones.** 48+27=(40+20)+(8+7)=60+15=75.\n\n**Step 3: Count on in parts.** 48→68 (+20)→75 (+7). Two jumps total 27.\n\n**Step 4: Check with inverse subtraction.** 75−27=48, confirming the original addition.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"12\" fill=\"#eef5f1\"/><text x=\"14\" y=\"28\" font-size=\"18\" font-family=\"Arial\" fill=\"#263b30\">Mental addition choices</text><rect x=\"10\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"23\" y=\"105\" font-size=\"18\" font-family=\"Arial\">LEARN</text><rect x=\"144\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"157\" y=\"105\" font-size=\"18\" font-family=\"Arial\">MODEL</text><rect x=\"278\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"291\" y=\"105\" font-size=\"18\" font-family=\"Arial\">TRY</text><rect x=\"412\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"425\" y=\"105\" font-size=\"18\" font-family=\"Arial\">CHECK</text></svg>","alt":"Four-part teaching guide for Mental Addition: Make Tens, Split and Check.","caption":"Learn, model, try and check."}],"guided_practice":"36+19=36+20−1=55. 64+28=64+20+8=92. 47+35=(40+30)+(7+5)=82. Verify 82−35=47. Explain why 58+26 is 84, not 74.","independent_task":"Calculate 58+26+17 twice, using compensation and partitioning or counting on. Show intermediate totals, an inverse check and a correction of ''58+26=74''.","response_prompt":"Calculate 58+26+17 twice, using compensation and partitioning or counting on. Show intermediate totals, an inverse check and a correction of ''58+26=74''.","quiz":[{"type":"multiple_choice","question":"48+27?","options":["65","75","85","74"],"correct_index":1,"explanation":"75 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"50+25?","options":["65","70","75","80"],"correct_index":2,"explanation":"75 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"36+19?","options":["54","55","56","65"],"correct_index":1,"explanation":"55 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"64+28?","options":["82","92","102","88"],"correct_index":1,"explanation":"92 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"47+35?","options":["72","82","92","81"],"correct_index":1,"explanation":"82 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"58+26?","options":["74","84","94","86"],"correct_index":1,"explanation":"84 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"58+26+17?","options":["91","101","111","100"],"correct_index":1,"explanation":"101 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"75−27?","options":["38","48","58","47"],"correct_index":1,"explanation":"48 is correct; review the relevant worked example and evidence."},{"type":"short_answer","question":"Complete the independent mental addition: make tens, split and check task with full working.","sample_answer":"58+26=84, then 84+17=101. Alternatively 58+17=75 then 75+26=101.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."},{"type":"short_answer","question":"Explain a topic-specific checking method or corrected mistake.","sample_answer":"58+26 is 84 because 58+20=78 and 78+6=84, not 74. Check 84−26=58.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."}],"parent_notes":"Parent: Check the child''s independent explanation and original written work.\n\nParent: Written answer model 1. 58+26=84, then 84+17=101. Alternatively 58+17=75 then 75+26=101.\n\nParent: Written answer model 2. 58+26 is 84 because 58+20=78 and 78+6=84, not 74. Check 84−26=58.\n\nParent: Manually review the written responses, keep evidence and verify NESA mapping. The eight MCQs need all eight correct for the existing 90% pass mark.","evidence_instructions":"Keep guided practice, the independent mental addition: make tens, split and check work, a correction and both written answers.","offline_alternative":"Work through the included teaching and questions on paper, then keep a photograph or typed evidence.","extension":"Design a new challenging mental addition: make tens, split and check question and solve it with a check.","stage_hints":{"accept":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach0":["Read the Make a friendly ten task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach1":["Read the Split into tens and ones task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach2":["Read the Count on in parts task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach3":["Read the Check with inverse subtraction task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"learn":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"guided":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"write":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"quiz":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"submit":["Read the Mental Addition: Make Tens, Split and Check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."]}}'),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE seed_key='s2-mat-y3-w05-l2';

UPDATE lessons SET title='Addition Columns: Exchange Ones and Tens',data=json_patch(data,'{"seed_key":"s2-mat-y3-w05-l3","title":"Addition Columns: Exchange Ones and Tens","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":5,"lesson_number":3,"duration_minutes":60,"child_mission":"Investigate addition columns: exchange ones and tens through an original worked model, practice and an independent challenge.","learning_intention":"We are learning to use addition columns: exchange ones and tens and explain why the method works.","success_criteria":["I can explain a taught concept in my own words.","I can follow a worked example and identify important steps.","I can complete guided practice with feedback.","I can solve an independent challenge.","I can check and explain one improvement."],"materials":["All examples and reading are provided.","Optional paper, pencil and counters."],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four key ideas","cards":[{"front":"Align each place","back":"Write ones below ones, tens below tens and hundreds below hundreds."},{"front":"Exchange ten ones","back":"When the ones add to ten or more, keep the ones and exchange ten ones for one ten."},{"front":"Include carried tens and hundreds","back":"Add the carried ten in the tens column and exchange ten tens for a hundred when necessary."},{"front":"Estimate then inverse-check","back":"Use rounded numbers to check whether the answer is sensible, then subtract for an exact check."}]}],"printable_resource":{"title":"Addition Columns: Exchange Ones and Tens","instructions":"Read, practise and complete the original challenge, then check.","passage":"A wildlife centre counted 168 birds in the first week and 257 in the next.","prompts":["What is given?","What is the useful method?","What did I find?","How did I check it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Align each place","explain":"**Understand:** Write ones below ones, tens below tens and hundreds below hundreds.\n\n**Original example:** A wildlife centre counted 168 birds in the first week and 257 in the next.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** For 168+257, align the 8 with 7, the 6 with 5, and the 1 with 2.\n\n**YOUR TURN:** 47+36: 7+6=13, carry a ten; 4+3+1=8 tens, giving 83. For 286+175, 6+5=11, carry; 8+7+1=16, carry; 2+1+1=4, giving 461. For 349+78, answer 427. Write columns yourself before checking.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Write ones below ones, tens below tens and hundreds below hundreds.","check":{"question":"168+257?","options":["415","425","435","525"],"correct_index":1,"explanation":"For 168+257, align the 8 with 7, the 6 with 5, and the 1 with 2."},"visual_before":[{"episode":{"title":"Learning Addition Columns: Exchange Ones and Tens","transcript":"Pip: Eight and seven make fifteen. Do I write fifteen in the ones box?\nJuno: Write five ones and carry one ten to the next place.\nPip: Then the tens column must include the carried one.\nJuno: Correct. Pause and work out six plus five plus one.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Eight and seven make fifteen. Do I write fifteen in the ones box?"},{"who":"juno","text":"Write five ones and carry one ten to the next place."},{"who":"pip","text":"Then the tens column must include the carried one."},{"who":"juno","text":"Correct. Pause and work out six plus five plus one.","pause_after":true}]}]}}]},{"icon":"📚","title":"Exchange ten ones","explain":"**Understand:** When the ones add to ten or more, keep the ones and exchange ten ones for one ten.\n\n**Original example:** A wildlife centre counted 168 birds in the first week and 257 in the next.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 8+7=15: write 5 in ones and carry 1 ten.\n\n**YOUR TURN:** 47+36: 7+6=13, carry a ten; 4+3+1=8 tens, giving 83. For 286+175, 6+5=11, carry; 8+7+1=16, carry; 2+1+1=4, giving 461. For 349+78, answer 427. Write columns yourself before checking.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"When the ones add to ten or more, keep the ones and exchange ten ones for one ten.","check":{"question":"8+7?","options":["14","15","16","5"],"correct_index":1,"explanation":"8+7=15: write 5 in ones and carry 1 ten."}},{"icon":"✍️","title":"Include carried tens and hundreds","explain":"**Understand:** Add the carried ten in the tens column and exchange ten tens for a hundred when necessary.\n\n**Original example:** A wildlife centre counted 168 birds in the first week and 257 in the next.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 6+5+1=12 tens: write 2 tens, carry 1 hundred. 1+2+1=4 hundreds, giving 425.\n\n**YOUR TURN:** 47+36: 7+6=13, carry a ten; 4+3+1=8 tens, giving 83. For 286+175, 6+5=11, carry; 8+7+1=16, carry; 2+1+1=4, giving 461. For 349+78, answer 427. Write columns yourself before checking.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Add the carried ten in the tens column and exchange ten tens for a hundred when necessary.","check":{"question":"Tens digit of 425?","options":["1","2","3","5"],"correct_index":1,"explanation":"6+5+1=12 tens: write 2 tens, carry 1 hundred. 1+2+1=4 hundreds, giving 425."}},{"icon":"✅","title":"Estimate then inverse-check","explain":"**Understand:** Use rounded numbers to check whether the answer is sensible, then subtract for an exact check.\n\n**Original example:** A wildlife centre counted 168 birds in the first week and 257 in the next.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 168≈170 and 257≈260: about 430. Actual 425; 425−257=168.\n\n**YOUR TURN:** 47+36: 7+6=13, carry a ten; 4+3+1=8 tens, giving 83. For 286+175, 6+5=11, carry; 8+7+1=16, carry; 2+1+1=4, giving 461. For 349+78, answer 427. Write columns yourself before checking.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Use rounded numbers to check whether the answer is sensible, then subtract for an exact check.","check":{"question":"47+36?","options":["73","83","93","84"],"correct_index":1,"explanation":"168≈170 and 257≈260: about 430. Actual 425; 425−257=168."}}],"worked_example":"**Original case:** A wildlife centre counted 168 birds in the first week and 257 in the next.\n\n**Step 1: Align each place.** For 168+257, align the 8 with 7, the 6 with 5, and the 1 with 2.\n\n**Step 2: Exchange ten ones.** 8+7=15: write 5 in ones and carry 1 ten.\n\n**Step 3: Include carried tens and hundreds.** 6+5+1=12 tens: write 2 tens, carry 1 hundred. 1+2+1=4 hundreds, giving 425.\n\n**Step 4: Estimate then inverse-check.** 168≈170 and 257≈260: about 430. Actual 425; 425−257=168.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"12\" fill=\"#eef5f1\"/><text x=\"14\" y=\"28\" font-size=\"18\" font-family=\"Arial\" fill=\"#263b30\">Exchange ten ones</text><rect x=\"10\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"23\" y=\"105\" font-size=\"18\" font-family=\"Arial\">LEARN</text><rect x=\"144\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"157\" y=\"105\" font-size=\"18\" font-family=\"Arial\">MODEL</text><rect x=\"278\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"291\" y=\"105\" font-size=\"18\" font-family=\"Arial\">TRY</text><rect x=\"412\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"425\" y=\"105\" font-size=\"18\" font-family=\"Arial\">CHECK</text></svg>","alt":"Four-part teaching guide for Addition Columns: Exchange Ones and Tens.","caption":"Learn, model, try and check."}],"guided_practice":"47+36: 7+6=13, carry a ten; 4+3+1=8 tens, giving 83. For 286+175, 6+5=11, carry; 8+7+1=16, carry; 2+1+1=4, giving 461. For 349+78, answer 427. Write columns yourself before checking.","independent_task":"Calculate 176+248+69 in two aligned addition stages. Show each carried value, round all three addends to tens to estimate, and use subtraction to verify. Explain the error in ''176+248=314''.","response_prompt":"Calculate 176+248+69 in two aligned addition stages. Show each carried value, round all three addends to tens to estimate, and use subtraction to verify. Explain the error in ''176+248=314''.","quiz":[{"type":"multiple_choice","question":"168+257?","options":["415","425","435","525"],"correct_index":1,"explanation":"425 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"8+7?","options":["14","15","16","5"],"correct_index":1,"explanation":"15 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Tens digit of 425?","options":["1","2","3","5"],"correct_index":1,"explanation":"2 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"47+36?","options":["73","83","93","84"],"correct_index":1,"explanation":"83 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"286+175?","options":["451","461","471","361"],"correct_index":1,"explanation":"461 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"349+78?","options":["417","427","437","426"],"correct_index":1,"explanation":"427 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"176+248?","options":["314","414","424","434"],"correct_index":2,"explanation":"424 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"176+248+69?","options":["483","493","503","593"],"correct_index":1,"explanation":"493 is correct; review the relevant worked example and evidence."},{"type":"short_answer","question":"Complete the independent addition columns: exchange ones and tens task with full working.","sample_answer":"176+248=424; 424+69=493. Nearest-ten estimate 180+250+70=500.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."},{"type":"short_answer","question":"Explain a topic-specific checking method or corrected mistake.","sample_answer":"The incorrect 314 omits regrouping. Six plus eight makes 14 ones, so carry one ten; seven plus four plus one makes 12 tens, so carry one hundred. 424−248=176.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."}],"parent_notes":"Parent: Check the child''s independent explanation and original written work.\n\nParent: Written answer model 1. 176+248=424; 424+69=493. Nearest-ten estimate 180+250+70=500.\n\nParent: Written answer model 2. The incorrect 314 omits regrouping. Six plus eight makes 14 ones, so carry one ten; seven plus four plus one makes 12 tens, so carry one hundred. 424−248=176.\n\nParent: Manually review the written responses, keep evidence and verify NESA mapping. The eight MCQs need all eight correct for the existing 90% pass mark.","evidence_instructions":"Keep guided practice, the independent addition columns: exchange ones and tens work, a correction and both written answers.","offline_alternative":"Work through the included teaching and questions on paper, then keep a photograph or typed evidence.","extension":"Design a new challenging addition columns: exchange ones and tens question and solve it with a check.","stage_hints":{"accept":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach0":["Read the Align each place task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach1":["Read the Exchange ten ones task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach2":["Read the Include carried tens and hundreds task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach3":["Read the Estimate then inverse-check task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"learn":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"guided":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"write":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"quiz":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"submit":["Read the Addition Columns: Exchange Ones and Tens task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."]}}'),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE seed_key='s2-mat-y3-w05-l3';

UPDATE lessons SET title='Addition Fluency: Accurate Facts With Reasons',data=json_patch(data,'{"seed_key":"s2-mat-y3-w05-l4","title":"Addition Fluency: Accurate Facts With Reasons","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":5,"lesson_number":4,"duration_minutes":60,"child_mission":"Investigate addition fluency: accurate facts with reasons through an original worked model, practice and an independent challenge.","learning_intention":"We are learning to use addition fluency: accurate facts with reasons and explain why the method works.","success_criteria":["I can explain a taught concept in my own words.","I can follow a worked example and identify important steps.","I can complete guided practice with feedback.","I can solve an independent challenge.","I can check and explain one improvement."],"materials":["All examples and reading are provided.","Optional paper, pencil and counters."],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four key ideas","cards":[{"front":"Use familiar bonds","back":"Facts to ten and twenty help solve new additions without starting at one."},{"front":"Bridge through twenty","back":"Split an addend to complete a friendly number first."},{"front":"Partition larger addends","back":"Group tens and ones separately and exchange ten ones for a ten."},{"front":"Check rather than racing","back":"Fluency includes understanding and accuracy; speed can improve later."}]}],"printable_resource":{"title":"Addition Fluency: Accurate Facts With Reasons","instructions":"Read, practise and complete the original challenge, then check.","passage":"Cards show 9+6, 14+7, 37+25 and 120+80.","prompts":["What is given?","What is the useful method?","What did I find?","How did I check it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Use familiar bonds","explain":"**Understand:** Facts to ten and twenty help solve new additions without starting at one.\n\n**Original example:** Cards show 9+6, 14+7, 37+25 and 120+80.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 9+6 becomes 10+5=15, because I moved one from six to nine.\n\n**YOUR TURN:** 8+7=15 by making ten; 13+8=21 by making twenty; 46+17=63 by tens and ones; 150+50=200. Why is 29+8=37, not 36? Because 29+1+7=37.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Facts to ten and twenty help solve new additions without starting at one.","check":{"question":"9+6?","options":["14","15","16","17"],"correct_index":1,"explanation":"9+6 becomes 10+5=15, because I moved one from six to nine."},"visual_before":[{"episode":{"title":"Learning Addition Fluency: Accurate Facts With Reasons","transcript":"Pip: Does fluency mean I must hurry even if I get mistakes?\nJuno: No. Show a reliable method and check it. Speed can improve through practice.\nPip: I''ll bridge through ten for nine plus six.\nJuno: Great. Pause and explain how to bridge through twenty for fourteen plus seven.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Does fluency mean I must hurry even if I get mistakes?"},{"who":"juno","text":"No. Show a reliable method and check it. Speed can improve through practice."},{"who":"pip","text":"I''ll bridge through ten for nine plus six."},{"who":"juno","text":"Great. Pause and explain how to bridge through twenty for fourteen plus seven.","pause_after":true}]}]}}]},{"icon":"📚","title":"Bridge through twenty","explain":"**Understand:** Split an addend to complete a friendly number first.\n\n**Original example:** Cards show 9+6, 14+7, 37+25 and 120+80.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 14+7=14+6+1=20+1=21.\n\n**YOUR TURN:** 8+7=15 by making ten; 13+8=21 by making twenty; 46+17=63 by tens and ones; 150+50=200. Why is 29+8=37, not 36? Because 29+1+7=37.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Split an addend to complete a friendly number first.","check":{"question":"14+7?","options":["20","21","22","23"],"correct_index":1,"explanation":"14+7=14+6+1=20+1=21."}},{"icon":"✍️","title":"Partition larger addends","explain":"**Understand:** Group tens and ones separately and exchange ten ones for a ten.\n\n**Original example:** Cards show 9+6, 14+7, 37+25 and 120+80.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 37+25=30+20+7+5=50+12=62.\n\n**YOUR TURN:** 8+7=15 by making ten; 13+8=21 by making twenty; 46+17=63 by tens and ones; 150+50=200. Why is 29+8=37, not 36? Because 29+1+7=37.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Group tens and ones separately and exchange ten ones for a ten.","check":{"question":"37+25?","options":["52","62","72","63"],"correct_index":1,"explanation":"37+25=30+20+7+5=50+12=62."}},{"icon":"✅","title":"Check rather than racing","explain":"**Understand:** Fluency includes understanding and accuracy; speed can improve later.\n\n**Original example:** Cards show 9+6, 14+7, 37+25 and 120+80.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** 120+80=200 because 12 tens+8 tens=20 tens. Subtraction 200−80=120 checks it.\n\n**YOUR TURN:** 8+7=15 by making ten; 13+8=21 by making twenty; 46+17=63 by tens and ones; 150+50=200. Why is 29+8=37, not 36? Because 29+1+7=37.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Fluency includes understanding and accuracy; speed can improve later.","check":{"question":"120+80?","options":["180","190","200","210"],"correct_index":2,"explanation":"120+80=200 because 12 tens+8 tens=20 tens. Subtraction 200−80=120 checks it."}}],"worked_example":"**Original case:** Cards show 9+6, 14+7, 37+25 and 120+80.\n\n**Step 1: Use familiar bonds.** 9+6 becomes 10+5=15, because I moved one from six to nine.\n\n**Step 2: Bridge through twenty.** 14+7=14+6+1=20+1=21.\n\n**Step 3: Partition larger addends.** 37+25=30+20+7+5=50+12=62.\n\n**Step 4: Check rather than racing.** 120+80=200 because 12 tens+8 tens=20 tens. Subtraction 200−80=120 checks it.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"12\" fill=\"#eef5f1\"/><text x=\"14\" y=\"28\" font-size=\"18\" font-family=\"Arial\" fill=\"#263b30\">Build addition fluency</text><rect x=\"10\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"23\" y=\"105\" font-size=\"18\" font-family=\"Arial\">LEARN</text><rect x=\"144\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"157\" y=\"105\" font-size=\"18\" font-family=\"Arial\">MODEL</text><rect x=\"278\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"291\" y=\"105\" font-size=\"18\" font-family=\"Arial\">TRY</text><rect x=\"412\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"425\" y=\"105\" font-size=\"18\" font-family=\"Arial\">CHECK</text></svg>","alt":"Four-part teaching guide for Addition Fluency: Accurate Facts With Reasons.","caption":"Learn, model, try and check."}],"guided_practice":"8+7=15 by making ten; 13+8=21 by making twenty; 46+17=63 by tens and ones; 150+50=200. Why is 29+8=37, not 36? Because 29+1+7=37.","independent_task":"Answer 7+8, 9+9, 16+7, 28+15, 56+27 and 180+40. Show a named method for four, explain 29+8, and create one addition/subtraction fact family.","response_prompt":"Answer 7+8, 9+9, 16+7, 28+15, 56+27 and 180+40. Show a named method for four, explain 29+8, and create one addition/subtraction fact family.","quiz":[{"type":"multiple_choice","question":"9+6?","options":["14","15","16","17"],"correct_index":1,"explanation":"15 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"14+7?","options":["20","21","22","23"],"correct_index":1,"explanation":"21 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"37+25?","options":["52","62","72","63"],"correct_index":1,"explanation":"62 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"120+80?","options":["180","190","200","210"],"correct_index":2,"explanation":"200 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"7+8?","options":["14","15","16","17"],"correct_index":1,"explanation":"15 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"16+7?","options":["22","23","24","25"],"correct_index":1,"explanation":"23 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"56+27?","options":["73","83","93","84"],"correct_index":1,"explanation":"83 is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"29+8?","options":["36","37","38","39"],"correct_index":1,"explanation":"37 is correct; review the relevant worked example and evidence."},{"type":"short_answer","question":"Complete the independent addition fluency: accurate facts with reasons task with full working.","sample_answer":"15,18,23,43,83,220 respectively. For 56+27, add 20 to make 76, then 7 to make 83.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."},{"type":"short_answer","question":"Explain a topic-specific checking method or corrected mistake.","sample_answer":"29+8=29+1+7=37. Check 37−8=29. Example fact family: 16+4=20 and 20−4=16.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."}],"parent_notes":"Parent: Check the child''s independent explanation and original written work.\n\nParent: Written answer model 1. 15,18,23,43,83,220 respectively. For 56+27, add 20 to make 76, then 7 to make 83.\n\nParent: Written answer model 2. 29+8=29+1+7=37. Check 37−8=29. Example fact family: 16+4=20 and 20−4=16.\n\nParent: Manually review the written responses, keep evidence and verify NESA mapping. The eight MCQs need all eight correct for the existing 90% pass mark.","evidence_instructions":"Keep guided practice, the independent addition fluency: accurate facts with reasons work, a correction and both written answers.","offline_alternative":"Work through the included teaching and questions on paper, then keep a photograph or typed evidence.","extension":"Design a new challenging addition fluency: accurate facts with reasons question and solve it with a check.","stage_hints":{"accept":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach0":["Read the Use familiar bonds task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach1":["Read the Bridge through twenty task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach2":["Read the Partition larger addends task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach3":["Read the Check rather than racing task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"learn":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"guided":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"write":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"quiz":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"submit":["Read the Addition Fluency: Accurate Facts With Reasons task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."]}}'),updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE seed_key='s2-mat-y3-w05-l4';

UPDATE lessons SET title='Nonfiction Navigator: Headings, Glossary and Index',data=json_patch(data,'{"seed_key":"s2-eng-y3-w06-l1","title":"Nonfiction Navigator: Headings, Glossary and Index","stage":"Stage 2","learning_area":"English","year_level":3,"week":6,"lesson_number":1,"duration_minutes":60,"child_mission":"Investigate nonfiction navigator: headings, glossary and index through an original worked model, practice and an independent challenge.","learning_intention":"We are learning to use nonfiction navigator: headings, glossary and index and explain why the method works.","success_criteria":["I can explain a taught concept in my own words.","I can follow a worked example and identify important steps.","I can complete guided practice with feedback.","I can solve an independent challenge.","I can check and explain one improvement."],"materials":["All examples and reading are provided.","Optional paper, pencil and counters."],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"The four key ideas","cards":[{"front":"Use headings to find sections","back":"A heading tells you what the following section is mainly about; a subheading divides the topic into smaller sections."},{"front":"Use a glossary for meaning","back":"A glossary lists important terms and defines them, often in alphabetical order."},{"front":"Use an index to find pages","back":"An index lists topics and page references, usually near the back of a book."},{"front":"Choose the feature to fit the question","back":"Choose an index for where, a glossary for meaning and a heading for the broad section''s topic."}]}],"printable_resource":{"title":"Nonfiction Navigator: Headings, Glossary and Index","instructions":"Read, practise and complete the original challenge, then check.","passage":"A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.","prompts":["What is given?","What is the useful method?","What did I find?","How did I check it?"]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Use headings to find sections","explain":"**Understand:** A heading tells you what the following section is mainly about; a subheading divides the topic into smaller sections.\n\n**Original example:** A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** If I want to learn where animals live, I search for the heading Habitats rather than reading every page.\n\n**YOUR TURN:** Original mini-book Night Animals: contents ''Where They Live'' p2, ''What They Eat'' p5. Glossary: nocturnal—active mainly at night; camouflage—a colour or pattern that helps blend in. Index: owl 3,6; bat 4,7. Check: the foods section is What They Eat; nocturnal means active mainly at night; bats appear on pages 4 and 7.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"A heading tells you what the following section is mainly about; a subheading divides the topic into smaller sections.","check":{"question":"Purpose of a heading?","options":["Name section topic","Define one technical word","List every page","Name the author"],"correct_index":0,"explanation":"If I want to learn where animals live, I search for the heading Habitats rather than reading every page."},"visual_before":[{"episode":{"title":"Learning Nonfiction Navigator: Headings, Glossary and Index","transcript":"Pip: Where does my information book mention platypuses?\nJuno: The index lists topics and page numbers. Look there first.\nPip: To understand predator, I should use the glossary.\nJuno: Exactly. Pause and find the best heading for animal habitats.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Where does my information book mention platypuses?"},{"who":"juno","text":"The index lists topics and page numbers. Look there first."},{"who":"pip","text":"To understand predator, I should use the glossary."},{"who":"juno","text":"Exactly. Pause and find the best heading for animal habitats.","pause_after":true}]}]}}]},{"icon":"📚","title":"Use a glossary for meaning","explain":"**Understand:** A glossary lists important terms and defines them, often in alphabetical order.\n\n**Original example:** A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** I find ''predator'' and read its definition: an animal that hunts another animal for food.\n\n**YOUR TURN:** Original mini-book Night Animals: contents ''Where They Live'' p2, ''What They Eat'' p5. Glossary: nocturnal—active mainly at night; camouflage—a colour or pattern that helps blend in. Index: owl 3,6; bat 4,7. Check: the foods section is What They Eat; nocturnal means active mainly at night; bats appear on pages 4 and 7.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"A glossary lists important terms and defines them, often in alphabetical order.","check":{"question":"Where to find meaning of nocturnal?","options":["Index","Glossary","Cover only","Title"],"correct_index":1,"explanation":"I find ''predator'' and read its definition: an animal that hunts another animal for food."}},{"icon":"✍️","title":"Use an index to find pages","explain":"**Understand:** An index lists topics and page references, usually near the back of a book.\n\n**Original example:** A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** ''Platypus 14, 19'' means information about platypuses occurs on pages 14 and 19. It does not mean there are fourteen or nineteen platypuses.\n\n**YOUR TURN:** Original mini-book Night Animals: contents ''Where They Live'' p2, ''What They Eat'' p5. Glossary: nocturnal—active mainly at night; camouflage—a colour or pattern that helps blend in. Index: owl 3,6; bat 4,7. Check: the foods section is What They Eat; nocturnal means active mainly at night; bats appear on pages 4 and 7.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"An index lists topics and page references, usually near the back of a book.","check":{"question":"Index numbers 4 and 7 represent?","options":["Number of bats","Pages","Word lengths","Ages"],"correct_index":1,"explanation":"''Platypus 14, 19'' means information about platypuses occurs on pages 14 and 19. It does not mean there are fourteen or nineteen platypuses."}},{"icon":"✅","title":"Choose the feature to fit the question","explain":"**Understand:** Choose an index for where, a glossary for meaning and a heading for the broad section''s topic.\n\n**Original example:** A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.\n\nExplain the connection between this example and the rule.","example":"**WATCH MY THINKING:** Where are bats mentioned? Check the index. What does nocturnal mean? Check the glossary. Which section explains food? Find the heading.\n\n**YOUR TURN:** Original mini-book Night Animals: contents ''Where They Live'' p2, ''What They Eat'' p5. Glossary: nocturnal—active mainly at night; camouflage—a colour or pattern that helps blend in. Index: owl 3,6; bat 4,7. Check: the foods section is What They Eat; nocturnal means active mainly at night; bats appear on pages 4 and 7.\n\n**CHECK:** Compare your reasoning with the worked example and correct one error.","notice":"Choose an index for where, a glossary for meaning and a heading for the broad section''s topic.","check":{"question":"Where to locate pages about owls?","options":["Glossary","Index","Title","Dedication"],"correct_index":1,"explanation":"Where are bats mentioned? Check the index. What does nocturnal mean? Check the glossary. Which section explains food? Find the heading."}}],"worked_example":"**Original case:** A made-up information book called River Creatures has headings Habitats and Food Chains, a glossary entry predator, and an index entry ''platypus 14, 19''.\n\n**Step 1: Use headings to find sections.** If I want to learn where animals live, I search for the heading Habitats rather than reading every page.\n\n**Step 2: Use a glossary for meaning.** I find ''predator'' and read its definition: an animal that hunts another animal for food.\n\n**Step 3: Use an index to find pages.** ''Platypus 14, 19'' means information about platypuses occurs on pages 14 and 19. It does not mean there are fourteen or nineteen platypuses.\n\n**Step 4: Choose the feature to fit the question.** Where are bats mentioned? Check the index. What does nocturnal mean? Check the glossary. Which section explains food? Find the heading.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"12\" fill=\"#eef5f1\"/><text x=\"14\" y=\"28\" font-size=\"18\" font-family=\"Arial\" fill=\"#263b30\">Find nonfiction information</text><rect x=\"10\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"23\" y=\"105\" font-size=\"18\" font-family=\"Arial\">LEARN</text><rect x=\"144\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"157\" y=\"105\" font-size=\"18\" font-family=\"Arial\">MODEL</text><rect x=\"278\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#d8e9df\"/><text x=\"291\" y=\"105\" font-size=\"18\" font-family=\"Arial\">TRY</text><rect x=\"412\" y=\"53\" width=\"125\" height=\"90\" rx=\"9\" fill=\"#e5eaf6\"/><text x=\"425\" y=\"105\" font-size=\"18\" font-family=\"Arial\">CHECK</text></svg>","alt":"Four-part teaching guide for Nonfiction Navigator: Headings, Glossary and Index.","caption":"Learn, model, try and check."}],"guided_practice":"Original mini-book Night Animals: contents ''Where They Live'' p2, ''What They Eat'' p5. Glossary: nocturnal—active mainly at night; camouflage—a colour or pattern that helps blend in. Index: owl 3,6; bat 4,7. Check: the foods section is What They Eat; nocturnal means active mainly at night; bats appear on pages 4 and 7.","independent_task":"Create a four-page imaginary nonfiction guide ''Australian Garden Wildlife''. Provide three useful headings, four accurately defined glossary terms (habitat, pollination, camouflage, native), and four alphabetically sorted index entries with page numbers. Answer where to find bees, what pollination means and where animals live, identifying the correct text feature.","response_prompt":"Create a four-page imaginary nonfiction guide ''Australian Garden Wildlife''. Provide three useful headings, four accurately defined glossary terms (habitat, pollination, camouflage, native), and four alphabetically sorted index entries with page numbers. Answer where to find bees, what pollination means and where animals live, identifying the correct text feature.","quiz":[{"type":"multiple_choice","question":"Purpose of a heading?","options":["Name section topic","Define one technical word","List every page","Name the author"],"correct_index":0,"explanation":"Name section topic is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Where to find meaning of nocturnal?","options":["Index","Glossary","Cover only","Title"],"correct_index":1,"explanation":"Glossary is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Index numbers 4 and 7 represent?","options":["Number of bats","Pages","Word lengths","Ages"],"correct_index":1,"explanation":"Pages is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Where to locate pages about owls?","options":["Glossary","Index","Title","Dedication"],"correct_index":1,"explanation":"Index is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Which heading describes animal diets?","options":["Where They Live","What They Eat","Book Credits","How to Draw"],"correct_index":1,"explanation":"What They Eat is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Meaning of camouflage?","options":["A nest","Blending-in colours or patterns","A compass","Nightfall"],"correct_index":1,"explanation":"Blending-in colours or patterns is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"How is an index normally organised?","options":["By random colour","Alphabetical topics and page numbers","By full story chapters only","In rhyme"],"correct_index":1,"explanation":"Alphabetical topics and page numbers is correct; review the relevant worked example and evidence."},{"type":"multiple_choice","question":"Where to understand pollination?","options":["Glossary","Index only","Book cover","Page number alone"],"correct_index":0,"explanation":"Glossary is correct; review the relevant worked example and evidence."},{"type":"short_answer","question":"Complete the independent nonfiction navigator: headings, glossary and index task with full working.","sample_answer":"Headings: Habitats; Pollinators; Garden Visitors. Glossary: habitat—the place an organism lives; pollination—the transfer of pollen that can enable plant reproduction; camouflage—features that help an organism blend into surroundings; native—occurring naturally in an area. Index: bee 2,3; butterfly 3; habitat 1; possum 4.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."},{"type":"short_answer","question":"Explain a topic-specific checking method or corrected mistake.","sample_answer":"To find bees I use the index; to define pollination I use the glossary; to locate general information on where animals live I use the Habitats heading. The index refers to pages, not to numbers of animals.","marking_guide":"Require accurate topic-specific steps and reasons.","explanation":"Show how the lesson method leads to the answer."}],"parent_notes":"Parent: Check the child''s independent explanation and original written work.\n\nParent: Written answer model 1. Headings: Habitats; Pollinators; Garden Visitors. Glossary: habitat—the place an organism lives; pollination—the transfer of pollen that can enable plant reproduction; camouflage—features that help an organism blend into surroundings; native—occurring naturally in an area. Index: bee 2,3; butterfly 3; habitat 1; possum 4.\n\nParent: Written answer model 2. To find bees I use the index; to define pollination I use the glossary; to locate general information on where animals live I use the Habitats heading. The index refers to pages, not to numbers of animals.\n\nParent: Manually review the written responses, keep evidence and verify NESA mapping. The eight MCQs need all eight correct for the existing 90% pass mark.","evidence_instructions":"Keep guided practice, the independent nonfiction navigator: headings, glossary and index work, a correction and both written answers.","offline_alternative":"Work through the included teaching and questions on paper, then keep a photograph or typed evidence.","extension":"Design a new challenging nonfiction navigator: headings, glossary and index question and solve it with a check.","stage_hints":{"accept":["Read the Nonfiction Navigator: Headings, Glossary and Index task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach0":["Read the Use headings to find sections task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach1":["Read the Use a glossary for meaning task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach2":["Read the Use an index to find pages task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"teach3":["Read the Choose the feature to fit the question task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"learn":["Read the Nonfiction Navigator: Headings, Glossary and Index task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"guided":["Read the Nonfiction Navigator: Headings, Glossary and Index task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"write":["Read the Nonfiction Navigator: Headings, Glossary and Index task carefully.","Find a useful piece of information in the lesson example.","Show each step in your reasoning, then test whether the result is accurate."],"quiz":["Read the Nonfiction Navigator: Headings, Glossary and Index task carefully.","Find a useful piece of info